#[{
	orderNumber: if ( !isEmpty(attributes.uriParams.'orderNumber' default "") ) attributes.uriParams.'orderNumber'
    	else if ( !isEmpty(vars.orderNumberValidation default "") ) vars.orderNumberValidation
		else ""
}]
